import pandas as pd

CATCH_ALL_POLICY_AREA = "Other"


def transform(row):
    policy_area = row["policy_area"]
    targets_bill = row["targets_specific_bill"]
    if policy_area is None or bool(pd.isna(policy_area)):
        raise StepRefused(
            f"filing {row['filing_id']} has no policy area, so whether it needs a "
            f"follow-up read cannot be decided"
        )
    if targets_bill is None or bool(pd.isna(targets_bill)):
        raise StepRefused(
            f"filing {row['filing_id']} has no judgment on whether it names a bill, so "
            f"whether it needs a follow-up read cannot be decided"
        )
    flagged = (not bool(targets_bill)) or str(policy_area) == CATCH_ALL_POLICY_AREA
    return {**row, "needs_followup": bool(flagged)}

import html as _html
import pathlib

import pandas as pd


STYLE = """
  body { font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
         margin: 2rem auto; max-width: 1040px; padding: 0 1rem; color: #1a1a1a; }
  h1 { font-size: 1.5rem; margin-bottom: .2rem; }
  .sub { color: #666; margin-top: 0; font-size: .9rem; }
  .note { background: #fff8e1; border: 1px solid #ffe082; padding: .55rem .8rem;
          border-radius: 6px; font-size: .82rem; color: #7a5b00; margin: 1rem 0 1.4rem; }
  table { border-collapse: collapse; width: 100%; font-size: .9rem; }
  th, td { text-align: left; padding: .5rem .6rem; border-bottom: 1px solid #ececec;
           vertical-align: top; }
  th { background: #fafafa; font-size: .72rem; text-transform: uppercase;
       letter-spacing: .04em; color: #555; }
  td.num { font-variant-numeric: tabular-nums; font-weight: 600; white-space: nowrap; }
  td.muted { color: #777; }
  .pill { background: #eef2ff; color: #3730a3; padding: .12rem .55rem;
          border-radius: 999px; font-size: .78rem; white-space: nowrap; }
  .flag-yes { color: #9a3412; font-weight: 600; }
  .flag-no { color: #9ca3af; }
"""


def _cell(value):
    return "<td>" + _html.escape(str(value)) + "</td>"


def transform(df, output_dir):
    pathlib.Path(output_dir).mkdir(parents=True, exist_ok=True)

    body_rows = []
    for _, row in df.iterrows():
        follow_up = bool(row["needs_followup"])
        follow_html = (
            "<td class='flag-yes'>Follow up</td>" if follow_up else "<td class='flag-no'>-</td>"
        )
        cells = (
            _cell(row["filing_id"])
            + _cell(row["client"])
            + "<td class='muted'>" + _html.escape(str(row["registrant"])) + "</td>"
            + _cell(row["filing_period"])
            + "<td class='num'>$" + format(int(row["amount_usd"]), ",") + "</td>"
            + "<td><span class='pill'>" + _html.escape(str(row["policy_area"])) + "</span></td>"
            + follow_html
            + _cell(row["primary_ask"])
        )
        body_rows.append("<tr>" + cells + "</tr>")

    flagged = int(df["needs_followup"].sum())
    html_doc = (
        "<!DOCTYPE html>\n<html lang='en'>\n<head>\n<meta charset='UTF-8'>\n"
        "<title>Tutorial Lobbying Triage</title>\n<style>" + STYLE + "</style>\n"
        "</head>\n<body>\n"
        "<h1>Tutorial Lobbying Triage Report</h1>\n"
        "<p class='sub'>" + str(len(df)) + " filings above the $50,000 threshold; "
        + str(flagged) + " flagged for follow-up.</p>\n"
        "<p class='note'>Synthetic sample data bundled with this tutorial \u2014 not live "
        "Senate LDA filings. This report is a reading aid, not a verdict.</p>\n"
        "<table>\n<thead><tr>"
        "<th>Filing</th><th>Client</th><th>Registrant</th><th>Period</th>"
        "<th>Reported spend</th><th>Policy area</th><th>Follow-up?</th><th>Primary ask</th>"
        "</tr></thead>\n<tbody>\n" + "\n".join(body_rows) + "\n</tbody>\n</table>\n"
        "</body>\n</html>\n"
    )

    out_path = pathlib.Path(output_dir) / "tutorial_triage_report.html"
    out_path.write_text(html_doc, encoding="utf-8")
    return pd.DataFrame([{"report_path": str(out_path), "filing_count": len(df)}])
